package com.bplus.share;
import android.app.*;import org.json.*;import java.util.*;
/** Chat-only bulk actions. Removing records never removes disk files. */
public final class ChatActions{
 public static void show(Activity a,String thread,Runnable refresh){new AppDialog(a).setTitle(R.string.chat_options).setItems(new String[]{a.getString(R.string.clear_file_cards),a.getString(R.string.clear_conversation),a.getString(R.string.send_all_files)},(d,n)->{if(n==2){sendAll(a,thread);return;}final boolean filesOnly=n==0;new AppDialog(a).setTitle(filesOnly?R.string.clear_file_cards:R.string.clear_conversation).setMessage(filesOnly?R.string.clear_file_cards_note:R.string.clear_conversation_note).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.action_delete,(confirm,k)->{synchronized(Store.class){JSONArray old=Store.thread(thread);Store.set("lastChatActionSnapshot_"+thread,old.toString());Store.saveThread(thread,filter(old,filesOnly));}refresh.run();}).show();}).show();}
 public static JSONArray filter(JSONArray old,boolean filesOnly){return ChatRules.clear(old,filesOnly);}

 private static void sendAll(Activity a,String thread){ArrayList<JSONObject> files=new ArrayList<>();JSONArray t=Store.thread(thread);for(int i=0;i<t.length();i++){JSONObject m=t.optJSONObject(i);if(m!=null&&m.optString("kind").equals("file"))files.add(m);}if(files.isEmpty()){android.widget.Toast.makeText(a,R.string.no_chat_files,1).show();return;}for(JSONObject m:files)if(!FileCards.available(a,m)){new AppDialog(a).setTitle(R.string.send_all_files).setMessage(m.optString("name")+"\n"+Attachments.explanation(a,Attachments.state(a,m))+"\n"+a.getString(R.string.share_batch_stopped)).setPositiveButton(android.R.string.ok,null).show();return;}JSONArray peers=Store.peers();ArrayList<JSONObject> targets=new ArrayList<>();ArrayList<String> names=new ArrayList<>();for(int i=0;i<peers.length();i++){JSONObject p=peers.optJSONObject(i);if(p!=null){targets.add(p);names.add(p.optString("name"));}}if(names.isEmpty()){android.widget.Toast.makeText(a,R.string.no_chats,1).show();return;}new AppDialog(a).setTitle(R.string.send_all_files).setItems(names.toArray(new String[0]),(d,n)->new AppDialog(a).setMessage(a.getString(R.string.send_all_files_note,files.size(),names.get(n))).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.send_now,(confirm,k)->{JSONObject target=targets.get(n);new Thread(()->{int ok=0;for(JSONObject m:files)if(FileCards.available(a,m)&&TransferService.sendToPeer(target,FileCards.uri(m),m.optString("name"),m.optLong("size")))ok++;final int sent=ok;a.runOnUiThread(()->android.widget.Toast.makeText(a,a.getString(R.string.forward_result,sent,files.size()),1).show());}).start();}).show()).show();}
}
